/** Canonical Family Log page/API handler independent from the legacy app.ts monolith. */
export async function familyLog(request:Request,ctx:AppContext):Promise<Response>{
  if(!ctx.member)return authRequiredResponse(ctx);
  try{return await familyLogImpl(request,ctx);}
  catch(error){
    if(error instanceof RequestBodyParseError||error instanceof FamilyLogBadRequest)return json({ok:false,error:error.message||'入力内容が不正です。',code:'BAD_REQUEST'},400);
    if(error instanceof FamilyLogForbidden)return json({ok:false,error:error.message||'この操作は許可されていません。',code:'FORBIDDEN'},403);
    throw error;
  }
}
